/// TF_DS_KV_SHARD: the prompt fetch's buffers, allocated once at open: the fetched rows bounded by `fetch_rows`
/// (64K rows, 18 MiB: a chunk's visible rows up to 64K compressed rows, or its union, or a block's at this

fn lap(e: *const Engine, eh: *const EngramHost, t: *u64) u64 {
    const now = pstamp(e, eh);
    defer t.* = now;
    return now - t.*;
}

/// A chunk's rows `ids` of table `t` by AIO (the pool's bytes, at ~0.07 s for 24,576 rows where the pool's preads take
/// ~0.5 s on one GB10): batches of a quarter of the ring's slots (two reads a row), all submitted (a submit reaps while the
/// ring is full), then waited for in order.
pub fn aioGather(aio: *engram_aio.Aio, t: engram_io.Table, ids: []const i64, out_w: []u8, out_s: []u8) !void {
    const def = @max(aio.slots / 4, 1);
    const per = if (aio.batch) |b| @min(def, b) else def; // TF_DS_ENGRAM_AIO_BATCH: an upper bound on a batch's rows
    var batch: [64]u64 = undefined;
    var first: usize = 0;
    var pending: usize = 0;
    errdefer for (0..pending) |i| aio.wait(batch[(first + i) % batch.len]) catch {};
    var at: usize = 0;
    while (at < ids.len) : (at += per) {
        if (pending == batch.len) {
            const oldest = batch[first];
            first = (first + 1) % batch.len;
            pending -= 1;
            try aio.wait(oldest);
        }
        const n = @min(per, ids.len - at);
        batch[(first + pending) % batch.len] = try aio.start(t, ids[at..][0..n], out_w[at * t.row_w ..][0 .. n * t.row_w], out_s[at * t.row_s ..][0 .. n * t.row_s]);
        pending += 1;
    }
    while (pending != 0) {
        const oldest = batch[first];
        first = (first + 1) % batch.len;
        pending -= 1;
        try aio.wait(oldest);
    }
}

/// The rows of one block of the indexer's scores for a chunk of `n` rows over `n_comp_end` compressed keys: as many as
/// keep the [rows, n_comp] keys within 2^26 / 4 elements, a multiple of 16 unless one block holds the whole chunk, so
/// every later block's views (vis + r0 * 8 and the rest) start on a 16-byte boundary, the alignment the kit's index
/// kernels were captured for (137,612 compressed keys gave 121-row blocks: MissingTritonVariant at the second). A row's
/// scores and picks are its own, so the block size changes no bits.
fn indexRowBlock(n: usize, n_comp_end: usize) usize {
    return @max(16, @min(n, (@as(usize, 1) << 26) / (4 * @max(n_comp_end, 1)) / 16 * 16));
}

/// TF_DS_EXACT_RESUME: `rows` rows of the ring at `ring` from position `p0`, to/from `dst`'s rows at `dst_row` (a row
/// `rb` bytes), in two copies when the ring wraps.
fn tailRowsCopy(e: *const Engine, ring: u64, dst: u64, dst_row: usize, rb: usize, p0: usize, rows: usize, from_ring: bool) !void {
    const slots = e.c.window;
    const slot = p0 % slots;
    const n1 = @min(rows, slots - slot);
    const src = ring + slot * rb;
    const dst1 = dst + dst_row * rb;
    if (from_ring) {
        try e.ops.copyRows(e.s, src, rb, dst1, rb, rb, n1);
        if (rows > n1) try e.ops.copyRows(e.s, ring, rb, dst1 + n1 * rb, rb, rb, rows - n1);
    } else {
        try e.ops.copyRows(e.s, dst1, rb, src, rb, rb, n1);
        if (rows > n1) try e.ops.copyRows(e.s, dst1 + n1 * rb, rb, ring, rb, rb, rows - n1);
    }
}

/// TF_DS_EXACT_RESUME: the tail takes this chunk's decoder input rows of the pass's last `window` positions (replayCut
/// runs before the decoder layers, on the rows they read).
fn tailStash(e: *const Engine, ch: *const Chunk, replay: usize) !void {
    const t = ch.tail orelse return;
    if (t.buf == 0) return;
    const c = e.c;
    const r = tailRows(ch.start, ch.n, replay, c.window);
    if (r[1] <= r[0]) return;
    const row_h = c.hc * c.hidden * 2;
    const row_p = c.hc * 4;
    try tailRowsCopy(e, t.buf, ch.h, r[0] - ch.start, row_h, r[0], r[1] - r[0], false);
    try tailRowsCopy(e, t.buf + c.window * row_h, ch.pre, r[0] - ch.start, row_p, r[0], r[1] - r[0], false);
    t.end = @max(t.end, r[1]);
    t.start = t.end -| c.window;
}

/// The decoder's bounded replay at its first layer (_forward_k's `replay`, CED's prefill): the layer's attention mixes
/// (the pending MoE post fused in) and its kv-source update over every row of the chunk, then the chunk cut to its rows
/// at positions >= replay, the streams and their pre copied down (h[first:], pre[first:]). The decoder layers then run
/// on those rows with no window key before replay and this layer's update done. False: an encoder-only chunk (no
/// row at or past replay), which ends here.
///
/// TF_DS_EXACT_RESUME: a resumed pass whose replay reaches before its start takes the rows [replay, start) from its
/// tail first (the previous pass's decoder input), so the decoder runs on [replay, chunk end) as a cold pass would.
pub fn replayCut(e: *const Engine, ch: *Chunk, cs: *const Caches, sh: *Shared, li: usize, replay: usize, host_pos: []i64) !bool {
    try attnMixes(e, ch, li);
    if (e.w.layers[li].comp_wkv == null) return error.NoKvSource;
    try kvSourceUpdate(e, ch, cs, sh, li);
    const c = e.c;
    const pre = if (ch.tail) |t| try tailPre(ch.start, replay, t) else 0;
    const first = @max(ch.start, replay) - ch.start;
    if (first >= ch.n) return false;
    const n = ch.n - first + pre;
    if (n > ch.cap or (pre > 0 and host_pos.len < n)) return error.ChunkTooLong;
    if (first > 0 or pre > 0) {
        const row_h = c.hc * c.hidden * 2;
        const row_p = c.hc * 4;
        try e.ops.copyRows(e.s, ch.h + first * row_h, row_h, ch.h_alt + pre * row_h, row_h, row_h, ch.n - first);
        if (pre > 0) try tailRowsCopy(e, ch.tail.?.buf, ch.h_alt, 0, row_h, replay, pre, true); // rows [0, pre)
        std.mem.swap(u64, &ch.h, &ch.h_alt);
        try e.ops.copyRows(e.s, ch.pre + first * row_p, row_p, ch.pre_f + pre * row_p, row_p, row_p, ch.n - first);
        if (pre > 0) try tailRowsCopy(e, ch.tail.?.buf + c.window * row_h, ch.pre_f, 0, row_p, replay, pre, true);
        std.mem.swap(u64, &ch.pre, &ch.pre_f);
        ch.start = replay;
        ch.n = n;
        // pos[first:]: a view, first * 8 bytes in (its alignment is the one the served kernels were specialized for). An odd
        // `first` leaves it off a 16-byte boundary, and the kit has no variant for some launches with such a view (a short
        // chunk's split attention: _sparse_attn_part with SPLITS > 1 and no row bases); the same positions copied, in the
        // stream's order, to a 16-byte boundary then: the kernels read the same values from an address they were captured for.
        if (pre > 0) {
            // the prepended rows' positions are not in pos0 (it starts at the pass's own start): [replay, replay + n)
            // written afresh to pos1 (16-byte aligned; host_pos is pageable, so the upload is staged before it returns)
            for (host_pos[0..n], 0..) |*p, i| p.* = @intCast(replay + i);
            try upload(e, ch.pos1, host_pos.ptr, n * 8);
            ch.pos = ch.pos1;
        } else if ((first * 8) % 16 != 0) { // (pos0 is 16-byte aligned: the view's alignment is first's)
            const src = ch.pos + first * 8;
            try e.d.check(e.d.api.cuMemcpyDtoDAsync_v2(ch.pos1, src, n * 8, e.s.handle), "cuMemcpyDtoDAsync");
            ch.pos = ch.pos1;
        } else ch.pos = ch.pos + first * 8;
    }
    try tailStash(e, ch, replay);
    return true;
}

/// DSpark tap j (_forward_k at a tap layer): a pending MoE gather posted into the streams first (hc_post, not fused),
/// then h.to(fp32).mean(1).to(bf16) into tap j's rows.
pub fn tap(e: *const Engine, ch: *Chunk, j: usize) !void {
    const c = e.c;
    try pendingPost(e, ch);
    try e.exact.hcMean4(e.s, ch.h, ch.taps + j * ch.cap * c.hidden * 2, c.hidden, ch.n, c.hidden);
}

/// Tap j's rows (bf16 [n, D]).
pub fn tapRows(e: *const Engine, ch: *const Chunk, j: usize) u64 {
    return ch.taps + j * ch.cap * e.c.hidden * 2;
}

/// The head on the chunk's last row (_forward_k without all_logits): the pending MoE post, collapse_norm of the row with
/// its pre, the head's columns (one row through the head's own group, fp32) and their gather: head_g holds the
/// prompt's logits, the ranks' columns in rank order.
pub fn head(e: *const Engine, ch: *Chunk) !void {
    const c = e.c;
    const n = ch.n;
    try pendingPost(e, ch);
    const last_h = ch.h + (n - 1) * c.hc * c.hidden * 2;
    const last_pre = ch.pre + (n - 1) * c.hc * 4;
    try tri_basic.collapseNorm(e.t, last_h, last_pre, e.w.norm, ch.head_x, c.eps, 1, c.hidden);
    const hl = e.w.head;
    try mmRows(e, ch, 1, hl, ch.head_x, c.hidden, ch.head_l, .fp32, hl.n);
    if (e.two) |t| return t.quarters(e, ch.head_l, ch.head_g, 1, t.hw, 4); // 2D: the vocabulary quarters, TP2's layout
    try e.comm.allGather(ch.head_l, ch.head_g, hl.n, .f32, e.s);
}

/// A layer's end: the MoE's gather is pending (the next layer's attention mixes post it) and the FFN's pre_out is the
/// next layer's pre (_forward_k's `pre, pre_f = pre_f, pre`).
pub fn endLayer(ch: *Chunk) void {
    ch.pending = true;
    std.mem.swap(u64, &ch.pre, &ch.pre_f);

            eh.ahead_n = n;
            eh.ahead_ready = .{ false, false };
            eh.chunk_hashed = false;
            eh.ahead_err = null;
            ahead = std.Thread.spawn(.{}, prompt.engramReadAhead, .{ eh, c, seq, start, n, @as(usize, 0) }) catch null;
        }
    }
    m.rs.ahead = ahead;
}

fn sliceRun(m: *Model, seq: []const i32, args: ChunkArgs, lo: usize, hi: usize) !SliceEnd {
    const e = &m.eng;
    const c = e.c;
    const ch = &m.ch;
    const rs = &m.rs;
    if (hi <= lo or hi > c.layers) return error.BadSlice;
    if (lo == 0) {
        m.dropChunk();
        try m.openChunk(seq, args);
    } else if (!rs.live or rs.next != lo or seq.len != rs.args.start + rs.args.n) return error.BadSlice;
    const start = rs.args.start;
    const n = rs.args.n;
    const replay = rs.args.replay;
    const pt = m.ptimer;
    const taps = m.dr != null;
    for (lo..hi) |li| {
        if (li == c.layers / 2) {
            if (!try prompt.replayCut(e, ch, &m.view, &rs.shared, li, replay, m.host_pos)) {
                // encoder-only: no synchronize either (as at the chunk's end below), so the next chunk's host steps
                // run while this one's last layers do; the profile alone waits
                if (pt) |t| {
                    try m.stream.synchronize();
                    try t.finish();
                }
                prefill_prof.finish();
                m.rs.reset();
                return .encoder_only;
            }
            rs.floor = replay;
            rs.kv_done = li;
        }
        if (e.w.layers[li].engram_wkv != null) {
            const eh = if (m.eh) |*x| x else return error.NoEngramTables;
            if (rs.ahead) |th| {
                th.join();
                rs.ahead = null;
            }
            if (eh.ahead_err) |err| return err;
            const j = std.mem.indexOfScalar(u16, c.engram_layers.slice(), @intCast(li)).?;
            if (eh.lead_on) try m.lead.before(eh, j, start, n); // (TF_DS_ENGRAM_LEAD: this layer's reader)
            try prompt.engramApply(e, ch, eh, li, seq);
            const ne = @min(2, c.engram_layers.slice().len);
            if (eh.lead_on) {
                // this layer's rows of the next chunk from now, a whole chunk ahead of their layer
                const more = moreRowsAfter(m.fill_seq, seq, start, n);
                const nn = if (more) @min(chunk_rows, m.fill_seq.len - start - n) else 0;
                m.lead.after(eh, c, seq, start, n, j, if (more) m.fill_seq[0 .. start + n + nn] else null, nn);
            } else if (j + 1 < ne) {
                if (!eh.ahead_ready[j + 1])
                    rs.ahead = std.Thread.spawn(.{}, prompt.engramReadAhead, .{ eh, c, seq, start, n, j + 1 }) catch null;
            } else if (m.fill_seq.len > start + n and m.fill_seq.ptr == seq.ptr) {
                // the next chunk's rows while this one's layers run
                const nn = @min(chunk_rows, m.fill_seq.len - start - n);
                eh.ahead_start = start + n;
                eh.ahead_n = nn;
                eh.ahead_ready = .{ false, false };
                eh.chunk_hashed = false;
                eh.ahead_err = null;
                m.ahead = std.Thread.spawn(.{}, prompt.engramReadAheadAll, .{ eh, c, m.fill_seq[0 .. start + n + nn], start + n, nn }) catch null;
            }
            if (pt) |t| try t.mark(m.stream, .engram);
            prefill_prof.mark(m.stream, .engram);
        }
        // a DSpark tap reads the streams after the layer's Engram (_forward_k's order)
        if (taps) if (std.mem.indexOfScalar(u16, c.dspark_taps.slice(), @intCast(li))) |j| try prompt.tap(e, ch, j);
        try prompt.attnMixes(e, ch, li);
        if (pt) |t| try t.mark(m.stream, .mix_attn);
        prefill_prof.mark(m.stream, .mix_attn);
        try prompt.attention(e, ch, &m.view, &rs.shared, li, m.ring_view[li], rs.floor, rs.kv_done != null and rs.kv_done.? == li);
        if (pt) |t| try t.mark(m.stream, .attn);
        prefill_prof.mark(m.stream, .attn);
        try prompt.gatherPartial(e, ch); // TF_DS_BF16_PARTIALS: bf16 on the wire, widened at the mixes
        if (pt) |t| try t.mark(m.stream, .gather_a);
        prefill_prof.mark(m.stream, .gather_a);
        try prompt.ffnMixes(e, ch, li);
        if (pt) |t| try t.mark(m.stream, .mix_ffn);
        prefill_prof.mark(m.stream, .mix_ffn);
        try prompt.moe(e, ch, li);
        if (pt) |t| try t.mark(m.stream, .moe);
        prefill_prof.mark(m.stream, .moe);
        // TF_DS_PREFILL_GATHER_OVERLAP: on the chunk's side stream (the next layer's Engram block overlaps it). The
        // phase mark below clocks the main stream's fork point then, not the gather: the chunk wall is the measure.
        try prompt.gatherAside(e, ch);
        if (pt) |t| try t.mark(m.stream, .gather_m);
        prefill_prof.mark(m.stream, .gather_m);
        prompt.endLayer(ch);
    }
    rs.next = hi;
    if (hi < c.layers) return .more;
    // TF_DS_HEAD_LAST_CHUNK (0188): only the pass's last chunk's head is the prompt's logits - an earlier chunk that
    // reached the decoder (the last window's rows straddling a chunk end) had it computed and thrown away, so its
    // fixed costs (collapse_norm, the head's own group, the gather) go. The chunk still returns .head: it reached the
    // head, it just had nothing to keep (fill_seq's test is the Engram read-ahead's "more rows after this chunk").
    if (!(m.head_last_chunk and moreRowsAfter(m.fill_seq, seq, start, n))) {
        try prompt.head(e, ch);
        if (pt) |t| try t.mark(m.stream, .head);
        prefill_prof.mark(m.stream, .head);
    }
    if (m.dr) |*dr| {
        // its taps (the tap layers side by side) into the slot's drafter rings
        const dw = c.hidden;
        for (0..c.dspark_taps.slice().len) |j| try e.ops.copyRows(e.s, prompt.tapRows(e, ch, j), dw * 2, dr.at + j * dw * 2, dr.taps_w * 2, dw * 2, ch.n);
        try dr.absorb(e, ch, &m.dpool.?, m.fill_slot, dr.at, ch.n, ch.start);
    }
    // no synchronize: the next chunk's host steps (its first Engram layer's hashing, table reads and decode, ~0.14 s
    // at 2,048 rows) run while this chunk's kernels do; readers of the results (the prompt's logits) synchronize.
    // The profile (--profile 2) times a chunk to its end, so it alone waits.
    if (pt) |t| {
        try m.stream.synchronize();
        try t.finish();
    }
    prefill_prof.finish();
    m.rs.reset();
    return .head;
}

/// The prompt's logits (its last row's, the ranks' columns in rank order) after a fill's last chunk.
pub fn promptLogits(m: *const Model) u64 {
    return m.ch.head_g;
}

/// One round over every stream's window (rows.windows, each with its stream's slot and extent): the forward,
/// and, in absorbRows, each window whose stream drafts has its rows' taps absorbed into its slot's drafter rings.
/// Split in two by 0160 so a round with TF_DS_ABSORB_AFTER_PICK runs the pick between them; without the switch
/// the callers keep the served order (forward, absorb, pick) and the same synchronizations.
/// TF_DS_RING_TRACE (ring_trace.zig): the records' live round number and dump cadence at the round boundary,
/// on both ranks alike (rank 1's frame loop lands here too).
fn tickTrace(m: *Model) void {
    if (m.ring) |r| r.traceTick(m.stream);
}

pub fn verify(m: *Model, rows: round.Rows) !void {
    m.tickTrace();
    if (!m.aheadParked()) m.joinAhead(); // a prompt chunk's Engram read-ahead shares the host buffers a round's Engram reads use
    const e = &m.eng;
    if (m.prof) try m.stream.synchronize(); // (the GPU idle, so the issue time shows whether the host keeps it fed)
    const t0 = m.now();
    try round.forward(e, &m.rd, &m.ch, &m.caches, m.rings, if (m.eh) |*x| x else null, &.{}, rows, m.request_cap, null, if (m.graphs) |*g| g else null);
    if (m.prof) {
        m.t_enqueue = m.now() - t0;
        try m.stream.synchronize();
        m.t_forward = m.now() - t0;
        if (m.timer) |t| try t.finish();
        if (m.rd.clk != 0) {
            var h: [1 + 2 * round.Round.max_clocks]u64 = undefined;
            const d = m.ctx.d;
            try d.check(d.api.cuMemcpyDtoH_v2(&h, m.rd.clk, h.len * 8), "cuMemcpyDtoH");
            const n = @min(h[0], round.Round.max_clocks);
            for (1..n) |i| {
                const tag = h[2 + 2 * i] & 0xff;
                m.clk_ph[tag] += h[1 + 2 * i] -% h[1 + 2 * (i - 1)];
                m.clk_cnt[tag] += 1;
            }
            m.clk_rounds += 1;
        }
    }
}

/// The served eager absorb (0160, split out of verify): window i's rows' taps into its slot's drafter rings at
/// their positions (absorb[i]: the window's stream drafts; rows past the ones the round keeps sit where the
/// drafter never reads, and the next window overwrites them). With TF_DS_ABSORB_AFTER_PICK the kernels are left
/// running under the host's accept and the pass frame's send; the drafter pass, stream-ordered after them on the
/// same stream, sees them (bit-identical: the pick reads rd.logits and writes amax, the absorb reads rd.taps and
/// writes the drafter rings - independent kernels of one forward). Without the switch this returns with the
/// absorb done, as the round's old order had it.
pub fn absorbRows(m: *Model, rows: round.Rows, absorb: []const bool) !void {
    const e = &m.eng;
    const t1 = m.now();
    if (m.dr) |*dr| {
        const wins = rows.windows orelse return error.BadRound;
        var items: [max_streams]draft.Item = undefined;
        var n: usize = 0;
        for (wins, absorb) |win, yes| {
            if (!yes) continue;
            items[n] = .{ .slot = @intCast(rows.slots.?[win.row]), .taps = m.rd.taps + win.row * dr.taps_w * 2, .n = win.n, .start = @intCast(rows.pos[win.row]) };
            n += 1;
        }
        if (n > 0) try dr.absorbMany(e, &m.ch, &m.dpool.?, items[0..n]);
    }
    // the profile's absorb_ms wants the kernels finished (the late path then overlaps nothing); without the
    // profile and with the switch on, the kernels run under the host's accept and the pass frame's send
    if (!m.absorb_after_pick or m.prof) {
        try m.stream.synchronize();
        if (m.prof) m.t_absorb = m.now() - t1;
    }
}

/// The rounds' GPU clocks (a profile): the forward's start and each stretch's ends, for its gaps.
pub fn useClock(m: *Model, marks: u8) !void {
    m.rd.clk_marks = marks == 1 or marks == 3;
    m.rd.clk_shard = marks == 4; // the sharded attention's parts alone (round.PhaseTimer.shardMark)

    }

    /// wl.to(bf16) * scale of `count` fp32 values (the indexer's head weights).
    pub fn bf16Scale(e: *const Exact, s: cuda.Stream, in: u64, out: u64, count: usize, scale: f32) !void {
        if (count == 0) return;
        var a: cuda.Args = .{};
        a.add(in);
        a.add(out);
        a.add(@as(u64, count));
        a.add(scale);
        a.add(@as(c_int, @intFromBool(e.pdl)));
        try cuda.launch.launch(e.k_bf16_scale, .{ .grid = .{ .x = blocks(count, 256) }, .block = .{ .x = 256 }, .pdl = e.pdl }, s, &a);
    }

    /// h.to(fp32).mean(1).to(bf16) of the streams h [rows, 4, d] bf16 into out [rows, d] (row stride os): a DSpark tap.
    pub fn hcMean4(e: *const Exact, s: cuda.Stream, h: u64, out: u64, os: usize, rows: usize, d: usize) !void {
        if (rows == 0) return;
        var a: cuda.Args = .{};
        a.add(h);
        a.add(out);
        a.add(@as(c_longlong, @intCast(os)));
        a.add(@as(c_int, @intCast(rows)));
        a.add(@as(c_int, @intCast(d)));
        a.add(@as(c_int, @intFromBool(e.pdl)));
        try cuda.launch.launch(e.k_hc_mean4, .{ .grid = .{ .x = @min(4096, blocks(rows * d, 256)) }, .block = .{ .x = 256 }, .pdl = e.pdl }, s, &a);
    }
};

/// The indexer's weight scale as Python computes it (idx_dim ** -0.5 * idx_heads ** -0.5) and torch passes it (fp32).
pub fn indexScale(idx_dim: usize, idx_heads: usize) f32 {
    const v = std.math.pow(f64, @floatFromInt(idx_dim), -0.5) * std.math.pow(f64, @floatFromInt(idx_heads), -0.5);
    return @floatCast(v);
}

