/// TF_DS_TAPS_PACKED's engagement banner (0265's one-shot swap pattern), at the arm's first write.
var taps_packed_noted = std.atomic.Value(bool).init(false);

/// DSpark tap j (_forward_k at a tap layer): a pending MoE gather posted into the streams first (hc_post, not fused),
/// then h.to(fp32).mean(1).to(bf16) into tap j's rows. TF_DS_TAPS_PACKED: tap j at column j * D of the row-major
/// [rows, taps * D] the drafter absorbs (the decode rounds' rd.taps layout), the completion copies gone; off: the
/// planar [taps, cap, D] planes the copies gather side by side.
pub fn tap(e: *const Engine, ch: *Chunk, j: usize) !void {
    const c = e.c;
    try pendingPost(e, ch);
    if (e.ops.taps_packed) {
        if (!taps_packed_noted.swap(true, .monotonic)) std.log.info("dsv41: TF_DS_TAPS_PACKED: prompt taps written in the drafter's row-major layout (first at tap {d}, {d} rows)", .{ j, ch.n });
        try e.exact.hcMean4(e.s, ch.h, ch.taps + j * c.hidden * 2, c.dspark_taps.slice().len * c.hidden, ch.n, c.hidden);
    } else try e.exact.hcMean4(e.s, ch.h, ch.taps + j * ch.cap * c.hidden * 2, c.hidden, ch.n, c.hidden);
}

/// Tap j's rows (bf16 [n, D]) in the planar layout (TF_DS_TAPS_PACKED off). Under the switch tap j sits at column
/// j * D of ch.taps' packed rows (row stride taps * D) instead and this is not a tap's rows.
pub fn tapRows(e: *const Engine, ch: *const Chunk, j: usize) u64 {
    return ch.taps + j * ch.cap * e.c.hidden * 2;
}

