```js
add(delta) {
  let { years=0, months=0, weeks=0, days=0, hours=0, minutes=0, seconds=0, ms=0 } = typeof delta === 'number' ? { ms: delta } : delta;
  // months/years first on calendar
  let y = this.year + years;
  let m = this.month - 1 + months;
  y += Math.floor(m / 12); m = ((m % 12) + 12) % 12;
  const dim = daysInMonth(y, m + 1);
  const d = Math.min(this.day, dim);
  // then fixed units on the timeline
  const base = toEpochMs({ year: y, month: m + 1, day: d, hour: this.hour, minute: this.minute, second: this.second, ms: this.ms });
  const addMs = ((weeks * 7 + days) * 86400000) + ((hours * 60 + minutes) * 60 + seconds) * 1000 + ms;
  return DateTime.fromEpoch(base + addMs);
}
```

