arguments.content:
'use strict';

/**
 * decimal.js — a small arbitrary-precision decimal arithmetic library.
 *
 * Numbers are exact decimal values (sign, digits, scale), so money and other
 * base-10 quantities never pick up binary floating-point error:
 *
 *     const { Decimal } = require('./decimal');
 *     new Decimal('0.1').add('0.2').toString();      // '0.3'
 *     new Decimal('1').div('3', 10).toString();      // '0.3333333333'
 *     new Decimal('2').sqrt(20).toString();          // '1.41421356237309504880'
 *
 * Every operation accepts plain values (number, string, bigint) wherever a
 * Decimal is expected and returns a new Decimal; nothing mutates. Results are
 * normalized (no leading/trailing fractional zeros, no negative zero).
 *
 * Rounding: `round`, `toFixed` and `div` round half away from zero at the
 * requested decimal place. `div` and `sqrt` take a precision (decimal places
 * kept, default Decimal.DEFAULT_PRECISION = 20); add/sub/mul are exact.
 *
 * Run the tests with:  node decimal.js
 */

const assert = require('assert');

const DEFAULT_PRECISION = 20;

// ---------------------------------------------------------------------------
// digit-array helpers — big-endian arrays of decimal digits 0..9
// ---------------------------------------------------------------------------

function trimLeadingZeros(digits) {
  if (digits.length === 0) return [0];
  let i = 0;
  while (i < digits.length - 1 && digits[i] === 0) i += 1;
  return digits.slice(i);
}

function cmpAbs(a, b) {
  if (a.length !== b.length) return a.length < b.length ? -1 : 1;
  for (let i = 0; i < a.length; i += 1) {
    if (a[i] !== b[i]) return a[i] < b[i] ? -1 : 1;
  }
  return 0;
}

function addAbs(a, b) {
  const n = Math.max(a.length, b.length);
  const out = new Array(n + 1).fill(0);
  let carry = 0;
  for (let i = 0; i < n; i += 1) {
    const s = (a[a.length - 1 - i] || 0) + (b[b.length - 1 - i] || 0) + carry;
    out[n - i] = s % 10;
    carry = (s / 10) | 0;
  }
  out[0] = carry;
  return trimLeadingZeros(out);
}

// requires a >= b
function subAbs(a, b) {
  const out = new Array(a.length).fill(0);
  let borrow = 0;
  for (let i = 0; i < a.length; i += 1) {
    let d = (a[a.length - 1 - i] || 0) - (b[b.length - 1 - i] || 0) - borrow;
    if (d < 0) {
      d += 10;
      borrow = 1;
    } else {
      borrow = 0;
    }
    out[a.length - 1 - i] = d;
  }
  return trimLeadingZeros(out);
}

function mulAbs(a, b) {
  if ((a.length === 1 && a[0] === 0) || (b.length === 1 && b[0] === 0)) return [0];
  const out = new Array(a.length + b.length).fill(0);
  for (let i = a.length - 1; i >= 0; i -= 1) {
    let carry = 0;
    for (let j = b.length - 1; j >= 0; j -= 1) {
      const idx = i + j + 1;
      const p = a[i] * b[j] + out[idx] + carry;
      out[idx] = p % 10;
      carry = (p / 10) | 0;
    }
    let idx = i;
    while (carry > 0) {
      const s = out[idx] + carry;
      out[idx] = s % 10;
      carry = (s / 10) | 0;
      idx -= 1;
    }
  }
  return trimLeadingZeros(out);
}

function divmodAbs(a, b) {
  if (b.length === 1 && b[0] === 0) throw new Error('division by zero');
  const multiples = [[0]];
  for (let i = 1; i <= 9; i += 1) multiples.push(mulAbs(b, [i]));
  const quotient = new Array(a.length).fill(0);
  let rem = [0];
  for (let i = 0; i < a.length; i += 1) {
    rem = trimLeadingZeros(rem.concat([a[i]]));
    let q = 9;
    while (q > 0 && cmpAbs(multiples[q], rem) > 0) q -= 1;
    quotient[i] = q;
    if (q > 0) rem = subAbs(rem, multiples[q]);
  }
  return { quotient: trimLeadingZeros(quotient), remainder: rem };
}

// ---------------------------------------------------------------------------
// parsing
// ---------------------------------------------------------------------------

function parseString(text) {
  const m = /^\s*([+-])?(\d*)(?:\.(\d*))?(?:[eE]([+-]?\d+))?\s*$/.exec(text);
  const intPart = m ? m[2] : '';
  const fracPart = m ? m[3] || '' : '';
  if (!m || (intPart === '' && fracPart === '')) throw new Error(`invalid decimal: ${text}`);
  const digits = (intPart + fracPart).split('').map(Number);
  const exp = m[4] ? parseInt(m[4], 10) : 0;
  return { sign: m[1] === '-' ? -1 : 1, digits, scale: fracPart.length - exp };
}

function coerce(value) {
  if (value instanceof Decimal) return { sign: value._sign, digits: value._digits.slice(), scale: value._scale };
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error(`invalid decimal: ${value}`);
    return parseString(String(value));
  }
  if (typeof value === 'string') return parseString(value);
  if (typeof value === 'bigint') return parseString(value.toString());
  throw new Error(`cannot convert ${typeof value} to Decimal`);
}

function assertPrecision(p) {
  if (!Number.isInteger(p) || p < 0) throw new Error('precision must be a non-negative integer');
}

// internal constructor: takes ownership of `digits`, normalizes
function make(sign, digits, scale) {
  const d = Object.create(Decimal.prototype);
  d._sign = sign;
  d._digits = digits;
  d._scale = scale;
  d._normalize();
  return d;
}

// zero-pads `digits` on the right to represent the same value at `toScale`
function scaleTo(digits, fromScale, toScale) {
  if (toScale === fromScale) return digits.slice();
  return digits.concat(new Array(toScale - fromScale).fill(0));
}

// ---------------------------------------------------------------------------

class Decimal {
  /** Accepts a Decimal, number, string or bigint (see the header). */
  constructor(value) {
    const parsed = coerce(value);
    this._sign = parsed.sign;
    this._digits = parsed.digits;
    this._scale = parsed.scale;
    this._normalize();
  }

  static from(value) {
    return value instanceof Decimal ? value : new Decimal(value);
  }

  static isDecimal(value) {
    return value instanceof Decimal;
  }

  static max(...values) {
    return values.reduce((a, b) => (a.compareTo(b) >= 0 ? a : Decimal.from(b)));
  }

  static min(...values) {
    return values.reduce((a, b) => (a.compareTo(b) <= 0 ? a : Decimal.from(b)));
  }

  _normalize() {
    while (this._scale < 0) {
      this._digits.push(0);
      this._scale += 1;
    }
    if (this._digits.every((d) => d === 0)) {
      this._sign = 1;
      this._digits = [0];
      this._scale = 0;
      return;
    }
    while (this._scale > 0 && this._digits[this._digits.length - 1] === 0) {
      this._digits.pop();
      this._scale -= 1;
    }
    this._digits = trimLeadingZeros(this._digits);
  }

  // -- state -----------------------------------------------------------------

  /** -1, 0 or 1. */
  get sign() {
    return this.isZero() ? 0 : this._sign;
  }

  /** Decimal places in the normalized representation. */
  get scale() {
    return this._scale;
  }

  isZero() {
    return this._digits.length === 1 && this._digits[0] === 0;
  }

  isNegative() {
    return this._sign < 0 && !this.isZero();
  }

  isPositive() {
    return this._sign > 0 && !this.isZero();
  }

  isInteger() {
    return this._scale === 0;
  }

  // -- arithmetic (all exact except div/sqrt, which take a precision) --------

  add(other) {
    const b = Decimal.from(other);
    const scale = Math.max(this._scale, b._scale);
    const a1 = scaleTo(this._digits, this._scale, scale);
    const b1 = scaleTo(b._digits, b._scale, scale);
    if (this._sign === b._sign) return make(this._sign, addAbs(a1, b1), scale);
    const c = cmpAbs(a1, b1);
    if (c === 0) return make(1, [0], 0);
    return c > 0 ? make(this._sign, subAbs(a1, b1), scale) : make(b._sign, subAbs(b1, a1), scale);
  }

  sub(other) {
    return this.add(Decimal.from(other).neg());
  }

  mul(other) {
    const b = Decimal.from(other);
    return make(this._sign * b._sign, mulAbs(this._digits, b._digits), this._scale + b._scale);
  }

  /** Quotient with `precision` decimal places (rounded half away from zero). */
  div(other, precision = DEFAULT_PRECISION) {
    assertPrecision(precision);
    const b = Decimal.from(other);
    if (b.isZero()) throw new Error('division by zero');
    const k = b._scale + precision - this._scale;
    let numerator = this._digits;
    let denominator = b._digits;
    if (k > 0) numerator = numerator.concat(new Array(k).fill(0));
    else if (k < 0) denominator = denominator.concat(new Array(-k).fill(0));
    const { quotient, remainder } = divmodAbs(numerator, denominator);
    const roundUp = cmpAbs(addAbs(remainder, remainder), denominator) >= 0;
    return make(this._sign * b._sign, roundUp ? addAbs(quotient, [1]) : quotient, precision);
  }

  /** Integer power (binary exponentiation; negative powers divide at `precision`). */
  pow(n, precision = DEFAULT_PRECISION) {
    if (!Number.isInteger(n)) throw new Error('pow requires an integer exponent');
    if (n === 0) return make(1, [1], 0);
    let e = Math.abs(n);
    let base = this;
    let result = make(1, [1], 0);
    while (e > 0) {
      if (e & 1) result = result.mul(base);
      e = Math.floor(e / 2);
      base = base.mul(base);
    }
    return n < 0 ? make(1, [1], 0).div(result, precision) : result;
  }

  /** Square root to `precision` decimal places (Newton's method, 8 guard digits). */
  sqrt(precision = DEFAULT_PRECISION) {
    assertPrecision(precision);
    if (this._sign < 0) throw new Error('sqrt requires a non-negative number');
    if (this.isZero()) return make(1, [0], 0);
    const working = precision + 8;
    let x = sqrtGuess(this);
    for (let i = 0; i < 64; i += 1) {
      const next = x.add(this.div(x, working)).div(make(1, [2], 0), working);
      if (next.compareTo(x) === 0) return next.round(precision);
      x = next;
    }
    return x.round(precision);
  }

  /** Rounded to `dp` decimal places, half away from zero (`dp` may be negative). */
  round(dp) {
    if (!Number.isInteger(dp)) throw new Error('round requires an integer decimal place count');
    if (this._scale <= dp) return make(this._sign, this._digits.slice(), this._scale);
    const drop = this._scale - dp;
    const m = this._digits.slice();
    while (m.length <= drop) m.unshift(0);
    const q = m.slice(0, m.length - drop);
    const roundUp = m[m.length - drop] >= 5;
    return make(this._sign, roundUp ? addAbs(q, [1]) : q, dp);
  }

  abs() {
    return make(1, this._digits.slice(), this._scale);
  }

  neg() {
    return make(-this._sign, this._digits.slice(), this._scale);
  }

  // -- comparison ------------------------------------------------------------

  compareTo(other) {
    const b = Decimal.from(other);
    if (this._sign !== b._sign) return this._sign < b._sign ? -1 : 1;
    const scale = Math.max(this._scale, b._scale);
    const c = cmpAbs(scaleTo(this._digits, this._scale, scale), scaleTo(b._digits, b._scale, scale));
    return this._sign > 0 ? c : -c;
  }

  eq(other) {
    return this.compareTo(other) === 0;
  }

  lt(other) {
    return this.compareTo(other) < 0;
  }

  lte(other) {
    return this.compareTo(other) <= 0;
  }

  gt(other) {
    return this.compareTo(other) > 0;
  }

  gte(other) {
    return this.compareTo(other) >= 0;
  }

  // -- conversion ------------------------------------------------------------

  toString() {
    if (this.isZero()) return '0';
    const sign = this._sign < 0 ? '-' : '';
    const d = this._digits;
    const s = this._scale;
    if (s === 0) return sign + d.join('');
    if (s < d.length) return `${sign}${d.slice(0, d.length - s).join('')}.${d.slice(d.length - s).join('')}`;
    return `${sign}0.${'0'.repeat(s - d.length)}${d.join('')}`;
  }

  /** Rounded to `dp` decimal places, formatted with exactly `dp` of them. */
  toFixed(dp) {
    if (!Number.isInteger(dp) || dp < 0) throw new Error('toFixed requires a non-negative integer');
    const s = this.round(dp).toString();
    if (dp === 0) return s;
    const dot = s.indexOf('.');
    const intPart = dot === -1 ? s : s.slice(0, dot);
    const frac = dot === -1 ? '' : s.slice(dot + 1);
    return `${intPart}.${frac.padEnd(dp, '0')}`;
  }

  /** Lossy: a float64, per JavaScript. */
  toNumber() {
    return Number(this.toString());
  }
}

// initial Newton guess: the float square root when it exists, else one from
// the leading digits and a halved decimal exponent (values beyond float range)
function sqrtGuess(d) {
  const num = d.toNumber();
  if (Number.isFinite(num) && num > 0) return new Decimal(String(Math.sqrt(num)));
  const digits = d._digits;
  const used = Math.min(15, digits.length);
  let a = 0;
  for (let i = 0; i < used; i += 1) a = a * 10 + digits[i];
  let t = digits.length - used - d._scale;
  if (t % 2 !== 0) {
    a *= 10;
    t -= 1;
  }
  return new Decimal(String(Math.sqrt(a))).mul(make(1, [1], -(t / 2)));
}

Decimal.DEFAULT_PRECISION = DEFAULT_PRECISION;

module.exports = { Decimal };

// ---------------------------------------------------------------------------
// tests — run with `node decimal.js`
// ---------------------------------------------------------------------------

const _tests = [];
function test(name, fn) {
  _tests.push([name, fn]);
}

test('parses and normalizes', () => {
  assert.strictEqual(new Decimal('1.5').toString(), '1.5');
  assert.strictEqual(new Decimal('1.50').toString(), '1.5');
  assert.strictEqual(new Decimal('-0.0').toString(), '0');
  assert.strictEqual(new Decimal('.5').toString(), '0.5');
  assert.strictEqual(new Decimal('5.').toString(), '5');
  assert.strictEqual(new Decimal('1e3').toString(), '1000');
  assert.strictEqual(new Decimal('1.5e-2').toString(), '0.015');
  assert.strictEqual(new Decimal('-2.5E+4').toString(), '-25000');
  assert.strictEqual(new Decimal(0.1).toString(), '0.1');
  assert.strictEqual(new Decimal(100n).toString(), '100');
  assert.strictEqual(new Decimal('00012.3400').toString(), '12.34');
  assert.strictEqual(new Decimal(new Decimal('2.5')).toString(), '2.5');
  for (const bad of ['abc', '', ' ', '1e', '--1', '1.2.3', NaN, Infinity, -Infinity, {}]) {
    assert.throws(() => new Decimal(bad), /invalid decimal|cannot convert/);
  }
});

test('adds and subtracts without float error', () => {
  assert.strictEqual(new Decimal('0.1').add('0.2').toString(), '0.3');
  assert.strictEqual(new Decimal('0.1').add(0.2).toString(), '0.3');
  assert.strictEqual(new Decimal('1').sub('0.9').toString(), '0.1');
  assert.strictEqual(new Decimal('-1.5').add('-2.25').toString(), '-3.75');
  assert.strictEqual(new Decimal('5').add('-5').toString(), '0');
  assert.strictEqual(new Decimal('12345678901234567890123').add('1').toString(), '12345678901234567890124');
  assert.strictEqual(new Decimal('0.001').add('0.000002').toString(), '0.001002');
  assert.strictEqual(new Decimal('-0.5').add('1').toString(), '0.5');
  assert.strictEqual(new Decimal('10').sub('10.5').toString(), '-0.5');
  assert.strictEqual(new Decimal('0').add('0').toString(), '0');
});

test('multiplies exactly', () => {
  assert.strictEqual(new Decimal('1.5').mul('1.5').toString(), '2.25');
  assert.strictEqual(new Decimal('0.1').mul('0.1').toString(), '0.01');
  assert.strictEqual(new Decimal('-1.5').mul('2').toString(), '-3');
  assert.strictEqual(new Decimal('123456789').mul('987654321').toString(), '121932631112635269');
  assert.strictEqual(new Decimal('0').mul('-5').toString(), '0');
  assert.strictEqual(new Decimal('1e300').mul('1e300').toString(), `1${'0'.repeat(600)}`);
  assert.strictEqual(new Decimal('0.0001').mul('0.0001').toString(), '0.00000001');
});

test('divides to a chosen precision', () => {
  assert.strictEqual(new Decimal('1').div('3', 20).toString(), '0.33333333333333333333');
  assert.strictEqual(new Decimal('2').div('3', 20).toString(), '0.66666666666666666667');
  assert.strictEqual(new Decimal('10').div('4').toString(), '2.5');
  assert.strictEqual(new Decimal('1').div('8').toString(), '0.125');
  assert.strictEqual(new Decimal('1').div('3', 0).toString(), '0');
  assert.strictEqual(new Decimal('2').div('3', 1).toString(), '0.7');
  assert.strictEqual(new Decimal('-2').div('3', 4).toString(), '-0.6667');
  assert.strictEqual(new Decimal('1').div('3', 5).toString(), '0.33333');
  assert.strictEqual(new Decimal('2').div('4', 5).toString(), '0.5');
  assert.throws(() => new Decimal('1').div('0'), /division by zero/);
  assert.throws(() => new Decimal('1').div('3', -1), /precision/);
});

test('pow with integer exponents', () => {
  assert.strictEqual(new Decimal('2').pow(10).toString(), '1024');
  assert.strictEqual(new Decimal('2').pow(-2).toString(), '0.25');
  assert.strictEqual(new Decimal('-2').pow(3).toString(), '-8');
  assert.strictEqual(new Decimal('-2').pow(2).toString(), '4');
  assert.strictEqual(new Decimal('1.5').pow(3).toString(), '3.375');
  assert.strictEqual(new Decimal('0').pow(0).toString(), '1');
  assert.strictEqual(new Decimal('5').pow(0).toString(), '1');
  assert.strictEqual(new Decimal('10').pow(-3, 5).toString(), '0.001');
  assert.throws(() => new Decimal('2').pow(1.5), /integer exponent/);
  assert.throws(() => new Decimal('0').pow(-1), /division by zero/);
});

test('sqrt at precision', () => {
  assert.strictEqual(new Decimal('2').sqrt(20).toString(), '1.41421356237309504880');
  assert.strictEqual(new Decimal('2').sqrt(30).toString(), '1.414213562373095048801688724210');
  assert.strictEqual(new Decimal('10').sqrt(10).toString(), '3.1622776602');
  assert.strictEqual(new Decimal('9').sqrt().toString(), '3');
  assert.strictEqual(new Decimal('0.25').sqrt().toString(), '0.5');
  assert.strictEqual(new Decimal('0').sqrt().toString(), '0');
  assert.throws(() => new Decimal('-1').sqrt(), /non-negative/);
});

test('rounds half away from zero', () => {
  assert.strictEqual(new Decimal('1.234').round(2).toString(), '1.23');
  assert.strictEqual(new Decimal('1.235').round(2).toString(), '1.24');
  assert.strictEqual(new Decimal('-1.235').round(2).toString(), '-1.24');
  assert.strictEqual(new Decimal('1.5').round(0).toString(), '2');
  assert.strictEqual(new Decimal('2.5').round(0).toString(), '3');
  assert.strictEqual(new Decimal('-2.5').round(0).toString(), '-3');
  assert.strictEqual(new Decimal('9.99').round(1).toString(), '10');
  assert.strictEqual(new Decimal('99.9').round(-1).toString(), '100');
  assert.strictEqual(new Decimal('1234.5').round(-2).toString(), '1200');
  assert.strictEqual(new Decimal('0.5').round(-1).toString(), '0');
  assert.strictEqual(new Decimal('1.23').round(5).toString(), '1.23');
  assert.strictEqual(new Decimal('0.001').round(2).toString(), '0');
});

test('toFixed pads and rounds', () => {
  assert.strictEqual(new Decimal('1.5').toFixed(3), '1.500');
  assert.strictEqual(new Decimal('2').toFixed(2), '2.00');
  assert.strictEqual(new Decimal('1.235').toFixed(2), '1.24');
  assert.strictEqual(new Decimal('-0.004').toFixed(2), '0.00'); // the rounded zero normalizes unsigned
  assert.strictEqual(new Decimal('9.99').toFixed(1), '10.0');
  assert.strictEqual(new Decimal('123.456').toFixed(0), '123');
  assert.strictEqual(new Decimal('-2.5').toFixed(0), '-3');
  assert.throws(() => new Decimal('1').toFixed(-1), /non-negative/);
});

test('compares across representations', () => {
  assert.ok(new Decimal('1.50').eq('1.5'));
  assert.ok(new Decimal('1.5').eq(1.5));
  assert.ok(!new Decimal('1.5').eq('1.51'));
  assert.ok(new Decimal('2').gt('1.999'));
  assert.ok(new Decimal('2').gte(2));
  assert.ok(new Decimal('-2').lt('-1.9'));
  assert.ok(new Decimal('-2').lte('-2'));
  assert.ok(new Decimal('0').eq('-0'));
  assert.strictEqual(new Decimal('1').compareTo('2'), -1);
  assert.strictEqual(new Decimal('2').compareTo('2'), 0);
  assert.strictEqual(new Decimal('3').compareTo('2'), 1);
  assert.strictEqual(new Decimal('-1').compareTo('-2'), 1);
  assert.strictEqual(new Decimal('-3').compareTo('2'), -1);
  assert.strictEqual(new Decimal('0.001').compareTo('0.0010'), 0);
});

test('sign and state helpers', () => {
  assert.strictEqual(new Decimal('-3.5').abs().toString(), '3.5');
  assert.strictEqual(new Decimal('3.5').neg().toString(), '-3.5');
  assert.strictEqual(new Decimal('-3.5').neg().toString(), '3.5');
  assert.ok(new Decimal('0').isZero());
  assert.ok(new Decimal('0').neg().isZero());
  assert.ok(new Decimal('-0.1').isNegative());
  assert.ok(!new Decimal('0').isNegative());
  assert.ok(new Decimal('2.0').isInteger());
  assert.ok(!new Decimal('2.5').isInteger());
  assert.strictEqual(new Decimal('-3.5').sign, -1);
  assert.strictEqual(new Decimal('3.5').sign, 1);
  assert.strictEqual(new Decimal('0').sign, 0);
  assert.strictEqual(new Decimal('2.50').scale, 1);
});

test('static helpers and conversions', () => {
  assert.strictEqual(Decimal.from('1.5').toString(), '1.5');
  assert.ok(Decimal.isDecimal(Decimal.from(1)));
  assert.ok(!Decimal.isDecimal('1'));
  assert.strictEqual(Decimal.max('1', '3.5', '2').toString(), '3.5');
  assert.strictEqual(Decimal.min('1', '3.5', '2').toString(), '1');
  assert.strictEqual(new Decimal('1.23456').toNumber(), 1.23456);
  assert.strictEqual(new Decimal('1e300').toNumber(), 1e300);
  assert.strictEqual(new Decimal('-2.75').toString(), '-2.75');
  assert.strictEqual(new Decimal('0.1').add(0.2).eq(0.3), true);
});

function runTests() {
  let passed = 0;
  let failed = 0;
  for (const [name, fn] of _tests) {
    try {
      fn();
      passed += 1;
      console.log(`  ok   ${name}`);
    } catch (err) {
      failed += 1;
      console.error(`  FAIL ${name}`);
      console.error(`       ${err && err.message}`);
    }
  }
  console.log(`decimal.js: ${passed} passed, ${failed} failed, ${_tests.length} total`);
  if (failed > 0) process.exitCode = 1;
}

if (require.main === module) runTests();

